import { browserTargetTool } from "./browser-target.mjs";

export const runnerPlaywrightNames = Object.freeze([
  "browser_snapshot",
  "browser_find",
  "browser_file_upload",
  "browser_drop",
  "browser_handle_dialog",
  "browser_navigate",
  "browser_navigate_back",
  "browser_tabs",
  "browser_resize",
  "browser_pdf_save",
  "browser_mouse_down",
  "browser_mouse_up",
  "browser_take_screenshot",
]);

export function runnerBrowserToolCatalog(original) {
  // Keep prompts general. Only give interaction advice that applies across common tasks; keep case-specific steps in tests.
  const selected = original
    .filter((tool) => runnerPlaywrightNames.includes(tool.name))
    .map((tool) =>
      tool.name === "browser_snapshot"
        ? {
            ...tool,
            description:
              "Capture an accessibility snapshot for extra context or to help identify a control or read content in a screenshot. Base verdicts on what the screenshots show. The compact tree can omit accessible names. If the task needs an omitted name, use browser_inspect_target on the current ref. An omitted name or a DOM label attribute alone leaves the computed name unverified.",
            inputSchema: {
              ...tool.inputSchema,
              properties: {
                ...tool.inputSchema.properties,
                depth: {
                  ...tool.inputSchema.properties.depth,
                  description:
                    "Optional maximum tree depth. Deeper elements, including controls, are omitted. An omitted element may still be visible in the screenshot. Leave unset to avoid limiting the snapshot by depth.",
                },
              },
            },
          }
        : tool.name === "browser_take_screenshot"
          ? {
              ...tool,
              description:
                "Capture a screenshot of the current page. Use it to identify visible controls and content for browser actions.",
            }
          : tool.name === "browser_tabs"
            ? {
                ...tool,
                description:
                  tool.description +
                  ' Only the owned default context is supported: omit isolatedContext or use "default". Named isolated contexts are unsupported.',
                inputSchema: {
                  ...tool.inputSchema,
                  properties: {
                    ...tool.inputSchema.properties,
                    isolatedContext: {
                      type: "string",
                      enum: ["default"],
                      description:
                        'Owned default context alias. Omit or use "default"; named isolated contexts are unsupported.',
                    },
                  },
                },
              }
            : tool,
    );
  if (selected.length !== runnerPlaywrightNames.length)
    throw new Error("Selected official Playwright tools missing");
  selected.push(browserTargetTool);
  const functions = selected.map((tool) => ({
    type: "function",
    name: tool.name,
    description: tool.description,
    parameters: tool.inputSchema,
    strict: false,
  }));
  return { selected, functions };
}
